learningData.weeklyRecords = Array.isArray(learningData.weeklyRecords) ? learningData.weeklyRecords : [];
const today = () => new Date().toISOString().slice(0, 10);
function touchTask(task) { if (task) task.updatedAt = new Date().toISOString(); }
const dateLabel = (date) => new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' }).replace('.', '');
const priorityNames = { urgent: 'Crítica', high: 'Alta', medium: 'Normal', low: 'Baixa' };
let toastTimer;
function showToast(message, tone = 'success') { const toast = $('#toast'); if (!toast) return; toast.textContent = message; toast.dataset.tone = tone; toast.classList.add('visible'); clearTimeout(toastTimer); toastTimer = setTimeout(() => toast.classList.remove('visible'), 2400); }
function updateThemeButton() { $('#themeButton').textContent = document.body.dataset.theme === 'dark' ? 'Modo claro' : 'Modo noturno'; }
updateThemeButton();
function save() { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); localStorage.setItem(INITIALIZED_KEY, 'true'); $('#lastSaved').textContent = `Salvo às ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`; persistBackend(); }
function persistBackend() { if (!window.PortalAccess?.Access?.token) return; fetch(`${window.PORTAL_API_BASE || ''}/api/state`, { method: 'PUT', headers: window.PortalAccess.authHeaders(), body: JSON.stringify({ tasks, deletedTaskIds: [...deletedTaskIds], billingHistory, mergeRows, learningData }) }).then(response => { if (!response.ok) throw new Error(`HTTP ${response.status}`); $('#lastSaved').textContent = `Sincronizado às ${new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}`; showToast('Alteração sincronizada'); }).catch(error => { console.error('Falha ao sincronizar demanda:', error); $('#lastSaved').textContent = 'Salvo neste computador; não sincronizado'; showToast('Salvo apenas neste computador', 'warning'); }); }
function saveHistory() { localStorage.setItem(HISTORY_KEY, JSON.stringify(billingHistory)); persistBackend(); }
function saveMergeQueue() { localStorage.setItem(MERGE_QUEUE_KEY, JSON.stringify(mergeRows)); persistBackend(); }
function saveLearning() { try { localStorage.setItem(LEARNING_KEY, JSON.stringify(learningData)); persistBackend(); } catch (error) { alert('O armazenamento do navegador ficou cheio. Remova arquivos grandes da biblioteca ou use arquivos menores.'); } }
function seedIfEmpty() { if (tasks.length || localStorage.getItem(INITIALIZED_KEY)) return; tasks = [{ id: newId(), title: 'Triar novas solicitações e definir o que entra hoje', due: today(), owner: 'Pedro', priority: 'urgent', recurrence: 'daily', notes: 'Reunião rápida de 10 minutos para dividir o plantão.', status: 'progress' }, { id: newId(), title: 'Responder pendências recebidas por e-mail', due: today(), owner: 'Eu', priority: 'high', recurrence: 'daily', notes: '', status: 'todo' }, { id: newId(), title: 'Consolidar relatório semanal', due: nextDate(3), owner: 'Pedro', priority: 'medium', recurrence: 'weekly', notes: '', status: 'todo' }]; save(); }
function nextDate(days) { const d = new Date(); d.setDate(d.getDate() + days); return d.toISOString().slice(0, 10); }
function nextOccurrence(date, recurrence) { const d = new Date(`${date}T12:00:00`); const current = new Date(`${today()}T12:00:00`); const advance = () => { if (recurrence === 'daily') d.setDate(d.getDate() + 1); if (recurrence === 'weekly') d.setDate(d.getDate() + 7); if (recurrence === 'fortnightly') d.setDate(d.getDate() + 14); if (recurrence === 'monthly') d.setMonth(d.getMonth() + 1); }; advance(); while (d <= current) advance(); return d.toISOString().slice(0, 10); }
function scopedTasks() { const user = window.PortalAccess?.Access?.user; const sectorIds = user?.sectorIds || (user?.sectorId ? [user.sectorId] : []); return user?.role === 'admin' ? tasks : tasks.filter(task => sectorIds.includes(task.sectorId)); }
window.refreshOwnerFilter = function() { const user = window.PortalAccess?.Access?.user; const users = user?.role === 'admin' ? (window.__portalUsers?.length ? window.__portalUsers : [user, ...(user?.teammates || [])]) : [user, ...(user?.teammates || [])].filter(item => item && (item.id === user.id || item.sectorId === user.sectorId)); const people = [...new Map(users.filter(Boolean).map(item => [item.displayName, item.displayName])).values()]; const peopleOptions = people.map(name => `<option value="${escapeHtml(name)}">${escapeHtml(name)}</option>`).join(''); $('#ownerFilter').innerHTML = ['<option value="all">Todos os responsáveis</option>', peopleOptions, '<option value="Ambos">Ambos</option>'].join(''); $('#taskOwner').innerHTML = peopleOptions + '<option value="Ambos">Ambos</option>'; $('#recordOwner').innerHTML = peopleOptions; };
window.refreshTaskCategory = function() { const user = window.PortalAccess?.Access?.user; const sectors = user?.role === 'admin' ? (window.PortalAccess.Access.sectors || []) : (user?.sectors || [{ id: user?.sectorId, name: user?.sectorName }]); $('#taskSectorChoice').innerHTML = sectors.filter(sector => sector?.id).map(sector => `<option value="${escapeHtml(sector.id)}">${escapeHtml(sector.name)}</option>`).join(''); const categories = user?.role === 'admin' ? [...new Set([...sectors.map(sector => sector.name), ...tasks.map(task => task.category).filter(Boolean)])] : sectors.map(sector => sector.name); $('#taskCategory').innerHTML = categories.map(category => `<option value="${escapeHtml(category)}">${escapeHtml(category)}</option>`).join(''); };
new MutationObserver(() => { const selected = weekRecords(); const sorted = [...selected].sort((a, b) => a.date.localeCompare(b.date) || a.kind.localeCompare(b.kind) || a.name.localeCompare(b.name)); [...$('#weeklyBody').children].forEach((row, index) => { if (row.children.length === 4) row.lastElementChild.insertAdjacentHTML('beforebegin', `<td>${escapeHtml(sorted[index]?.createdBy || 'Não informado')}</td>`); }); }).observe($('#weeklyBody'), { childList: true });
function taskPeriod(task) { return { start: task.periodStart || task.due, end: task.periodEnd || task.due }; }
function visibleTasks() { const owner = $('#ownerFilter').value, priority = $('#priorityFilter').value, status = $('#statusFilter').value, search = $('#searchInput').value.toLowerCase(), filterStart = $('#periodFilterStart').value, filterEnd = $('#periodFilterEnd').value, current = today(); return scopedTasks().filter(t => { const period = taskPeriod(t); const statOk = !activeStatFilter || (activeStatFilter === 'today' && period.start <= current && t.status !== 'done') || (activeStatFilter === 'overdue' && period.end < current && t.status !== 'done') || (activeStatFilter === 'progress' && t.status === 'progress') || (activeStatFilter === 'done' && t.status === 'done'); const viewOk = activeStatFilter || currentView === 'all' || (currentView === 'today' ? period.start <= current : period.start > current); const periodOk = (!filterStart || period.end >= filterStart) && (!filterEnd || period.start <= filterEnd); return statOk && viewOk && periodOk && (activeStatFilter || currentView === 'all' || t.status !== 'done') && (status === 'all' || normalizedStatus(t) === status) && (owner === 'all' || t.owner === owner) && (priority === 'all' || t.priority === priority) && (!search || `${t.title} ${t.notes} ${t.owner}`.toLowerCase().includes(search)); }).sort((a,b) => (a.status === 'done') - (b.status === 'done') || a.due.localeCompare(b.due) || ['urgent','high','medium','low'].indexOf(a.priority) - ['urgent','high','medium','low'].indexOf(b.priority)); }
function groupTaskCards(items) { const list = $('#taskList'); const groups = new Map(); [...list.children].forEach((card, index) => { const task = items[index]; const period = taskPeriod(task); card.classList.add(`priority-${task.priority}`); const key = task.status === 'done' ? 'Concluídas' : period.end < today() ? 'Atrasadas' : period.start <= today() ? 'Hoje' : 'Planejadas'; if (!groups.has(key)) groups.set(key, []); groups.get(key).push(card); }); list.replaceChildren(); groups.forEach((cards, label) => { const heading = document.createElement('h3'); heading.className = 'task-group-title'; heading.textContent = label; list.append(heading, ...cards); }); }
let groupingTasks = false;
new MutationObserver(() => { if (groupingTasks || !$('#taskList').children.length || $('#taskList').firstElementChild.classList.contains('task-group-title')) return; groupingTasks = true; groupTaskCards(visibleTasks()); groupingTasks = false; }).observe($('#taskList'), { childList: true });
function reportTasks() { const start = $('#reportStart')?.value || ''; const end = $('#reportEnd')?.value || ''; const inRange = date => (!start || date >= start) && (!end || date <= end); return scopedTasks().filter(task => inRange(task.status === 'done' && task.completedAt ? task.completedAt.slice(0, 10) : task.due)); }
function dateTimeLabel(value) { return value ? new Date(value).toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' }) : 'Não registrado'; }
function normalizedStatus(task) { return task.status === 'done' ? 'done' : task.status === 'progress' ? 'progress' : 'todo'; }
function normalizeTasks(items) { return items.map(task => ({ ...task, owner: task.owner === 'Dupla' ? 'Pedro' : task.owner, status: normalizedStatus(task), createdAt: task.createdAt || null, updatedAt: task.updatedAt || task.createdAt || null, completedAt: task.completedAt || null, checklist: Array.isArray(task.checklist) ? task.checklist : [], attachments: Array.isArray(task.attachments) ? task.attachments : [] })); }
function categoryLabel(category) { return { cadastro: 'Cadastro', faturamento: 'Faturamento' }[category] || category || 'Sem categoria'; }
function periodLabel(task) { const start = task.periodStart || task.due; const end = task.periodEnd || task.due; return start && end && start !== end ? `${dateLabel(start)} a ${dateLabel(end)}` : dateLabel(end); }
function renderChecklistEditor() { $('#checklistItems').innerHTML = checklistDraft.map((item, index) => `<div class="checklist-editor-row"><input type="checkbox" data-checklist-draft-toggle="${index}" ${item.done ? 'checked' : ''}><span>${escapeHtml(item.text)}</span><button type="button" data-checklist-draft-remove="${index}" aria-label="Remover etapa">×</button></div>`).join(''); }
function renderAttachmentEditor() { $('#taskAttachmentList').innerHTML = attachmentDraft.map((item, index) => `<div class="attachment-row"><a href="${item.data}" download="${escapeHtml(item.name)}">📎 ${escapeHtml(item.name)}</a><small>${escapeHtml(item.size)}</small><button type="button" data-attachment-remove="${index}" aria-label="Remover anexo">×</button></div>`).join(''); }
function taskDetailsHtml(task) { const checklist = task.checklist || []; const attachments = task.attachments || []; const checklistHtml = checklist.length ? `<div class="task-checklist-inline">${checklist.map((item, index) => `<label class="task-check ${item.done ? 'done' : ''}"><input type="checkbox" data-checklist-task="${task.id}" data-checklist-index="${index}" ${item.done ? 'checked' : ''}>${escapeHtml(item.text)}</label>`).join('')}</div>` : ''; const attachmentHtml = attachments.length ? `<div class="task-attachments-inline">${attachments.map(item => `<a href="${item.data}" download="${escapeHtml(item.name)}">📎 ${escapeHtml(item.name)}</a>`).join('')}</div>` : ''; return checklistHtml + attachmentHtml; }
function addTaskChecklistItem(task) { const text = prompt('Nova etapa do checklist:'); if (!text?.trim()) return; task.checklist ||= []; task.checklist.push({ id: newId(), text: text.trim(), done: false }); touchTask(task); save(); render(); }
function renderCalendar() { const grid = $('#calendarGrid'); if (!grid) return; const year = calendarCursor.getFullYear(); const month = calendarCursor.getMonth(); const firstDay = (new Date(year, month, 1).getDay() + 6) % 7; const days = new Date(year, month + 1, 0).getDate(); const monthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric' }).format(calendarCursor); $('#calendarMonth').textContent = monthLabel.charAt(0).toUpperCase() + monthLabel.slice(1); const cells = []; for (let index = 0; index < firstDay; index += 1) cells.push('<span class="calendar-day outside"></span>'); for (let day = 1; day <= days; day += 1) { const date = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`; const dayTasks = scopedTasks().filter(task => { const period = taskPeriod(task); return period.start <= date && period.end >= date; }); const dots = dayTasks.slice(0, 12).map(task => `<i class="calendar-dot ${task.priority}" title="${escapeHtml(task.title)}"></i>`).join(''); const more = dayTasks.length > 12 ? `<span class="calendar-more">+${dayTasks.length - 12} demandas</span>` : ''; const todayClass = date === today() ? 'today' : ''; cells.push(`<button type="button" class="calendar-day ${todayClass}" data-calendar-date="${date}"><span class="calendar-day-number">${day}</span><span class="calendar-dots">${dots}</span>${more}</button>`); } grid.innerHTML = cells.join(''); }
function render() { const list = $('#taskList'); const items = visibleTasks(); list.innerHTML = items.map(task => { const period = taskPeriod(task); const overdue = period.end < today() && task.status !== 'done'; const isToday = period.start <= today() && period.end >= today(); const checklist = task.checklist || []; const checked = checklist.filter(item => item.done).length; const checklistHtml = checklist.length ? `<div class="task-checklist-summary">Checklist ${checked}/${checklist.length} concluído</div>` : '<button type="button" class="task-action checklist-add-inline" data-action="add-checklist" data-id="'+task.id+'">+ Adicionar etapa</button>'; const attachmentHtml = task.attachments?.length ? `<span class="task-attachment-count">📎 ${task.attachments.length}</span>` : ''; const currentUser = window.PortalAccess?.Access?.user; const claimHtml = currentUser && task.owner !== currentUser.displayName && task.status !== 'done' ? `<button class="task-action" data-action="claim" data-id="${task.id}">Assumir</button>` : ''; return `<article class="task ${task.status === 'done' ? 'completed' : ''}"><button class="check" data-action="toggle" data-id="${task.id}" aria-label="Concluir demanda"></button><div><div class="task-title">${escapeHtml(task.title)}</div>${task.notes ? `<div class="task-notes">${escapeHtml(task.notes)}</div>` : ''}<div class="meta"><span class="badge category-cadastro">${escapeHtml(categoryLabel(task.category))}</span><span class="badge priority-${task.priority}">${priorityNames[task.priority]}</span><span class="due ${overdue ? 'overdue' : isToday ? 'today' : ''}">${overdue ? 'Atrasada · ' : isToday ? 'Hoje · ' : ''}${periodLabel(task)}</span>${task.recurrence !== 'none' ? `<span class="due">↻ ${recurrenceName(task.recurrence)}</span>` : ''}${attachmentHtml}</div>${checklistHtml}${taskDetailsHtml(task)}<div class="task-dates">Criada: ${dateTimeLabel(task.createdAt)} · ${task.status === 'done' ? `Concluída: ${dateTimeLabel(task.completedAt)}` : 'Ainda não concluída'}</div></div><div class="task-actions"><span class="owner">${escapeHtml(task.owner)}</span>${claimHtml}<button class="task-action" data-action="edit" data-id="${task.id}">Editar</button><button class="delete" data-action="delete" data-id="${task.id}" aria-label="Excluir demanda">×</button></div></article>`; }).join(''); $('#emptyState').classList.toggle('hidden', items.length > 0); document.querySelectorAll('.stat-filter').forEach(card => card.classList.toggle('selected', card.dataset.statFilter === activeStatFilter)); updateStats(); renderCalendar(); }
function recurrenceName(value) { return { daily: 'diária', weekly: 'semanal', fortnightly: 'quinzenal', monthly: 'mensal' }[value] || ''; }
function updateStats() { const visible = scopedTasks(); const current = today(); const monthStart = `${current.slice(0, 7)}-01`; const monthEnd = new Date(Number(current.slice(0, 4)), Number(current.slice(5, 7)), 0).toISOString().slice(0, 10); const inMonth = task => { const period = taskPeriod(task); return period.start <= monthEnd && period.end >= monthStart; }; const completedInMonth = task => task.completedAt?.slice(0, 7) === current.slice(0, 7); const todayTasks = visible.filter(t => taskPeriod(t).start <= current && t.status !== 'done'); const overdueTasks = visible.filter(t => taskPeriod(t).end < current && t.status !== 'done'); const progressTasks = visible.filter(t => t.status === 'progress'); const doneTasks = visible.filter(t => t.status === 'done'); $('#todayCount').textContent = todayTasks.length; $('#overdueCount').textContent = overdueTasks.length; $('#progressCount').textContent = progressTasks.length; $('#doneCount').textContent = doneTasks.length; $('#todayMonthCount').textContent = `No mês: ${todayTasks.filter(inMonth).length}`; $('#overdueMonthCount').textContent = `No mês: ${overdueTasks.filter(inMonth).length}`; $('#progressMonthCount').textContent = `No mês: ${progressTasks.filter(inMonth).length}`; $('#doneMonthCount').textContent = `No mês: ${doneTasks.filter(completedInMonth).length}`; }
function setDisplayMode(mode) { displayMode = mode; const calendar = mode === 'calendar'; $('#taskList').classList.toggle('hidden', calendar); $('#emptyState').classList.toggle('hidden', calendar || $('#taskList').children.length > 0); $('#calendarPanel').classList.toggle('hidden', !calendar); $('#listViewButton').classList.toggle('active', !calendar); $('#calendarViewButton').classList.toggle('active', calendar); if (calendar) renderCalendar(); }
function openCalendarDay(date) { calendarSelectedDate = date; const tasksForDay = scopedTasks().filter(task => { const period = taskPeriod(task); return period.start <= date && period.end >= date; }); $('#calendarDayTitle').textContent = new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { weekday: 'long', day: '2-digit', month: 'long' }); $('#calendarDayList').innerHTML = tasksForDay.length ? tasksForDay.map(task => `<article class="calendar-day-task"><strong>${escapeHtml(task.title)}</strong><span>${escapeHtml(task.owner)} · ${escapeHtml(periodLabel(task))}</span>${taskDetailsHtml(task)}<div class="calendar-task-actions"><button type="button" data-calendar-action="toggle" data-id="${task.id}">${task.status === 'done' ? 'Reabrir' : 'Concluir'}</button>${task.owner !== window.PortalAccess?.Access?.user?.displayName && task.status !== 'done' ? `<button type="button" data-calendar-action="claim" data-id="${task.id}">Assumir</button>` : ''}<button type="button" data-calendar-action="edit" data-id="${task.id}">Editar</button></div></article>`).join('') : '<p class="empty-state">Nenhuma demanda neste dia.</p>'; $('#calendarDayDialog').showModal(); }
function claimTask(task) { const user = window.PortalAccess?.Access?.user; if (!task || !user) return; task.owner = user.displayName; task.assignedAt = new Date().toISOString(); touchTask(task); showToast(`Demanda assumida por ${user.displayName}`); }
function resourceKind(item) { if (item.type === 'application/pdf' || item.name.match(/\.pdf$/i)) return 'PDF'; if (item.type.includes('sheet') || item.name.match(/\.xlsx?$/i)) return 'XLS'; if (item.type.includes('word') || item.name.match(/\.docx?$/i)) return 'DOC'; return 'IMG'; }
function renderLearning() { const query = ($('#learningSearch')?.value || '').toLowerCase(); const resources = learningData.resources.filter(item => item.name.toLowerCase().includes(query)); $('#learningResources').innerHTML = resources.map((item, index) => `<div class="resource-item"><span class="resource-icon">${resourceKind(item)}</span><div><strong>${escapeHtml(item.name)}</strong><small>${item.size} · ${new Date(item.createdAt).toLocaleDateString('pt-BR')}</small></div><button class="icon-action" data-learning-delete="resource" data-index="${learningData.resources.indexOf(item)}">×</button><a class="icon-action" href="${item.data}" download="${escapeHtml(item.name)}">Baixar</a></div>`).join(''); $('#learningEmpty').classList.toggle('hidden', resources.length > 0); $('#learningLinks').innerHTML = learningData.links.map((item, index) => `<div class="resource-item"><span class="resource-icon link-icon">↗</span><div><a href="${escapeHtml(item.url)}" target="_blank" rel="noreferrer"><strong>${escapeHtml(item.title)}</strong></a><small>${escapeHtml(item.url)}</small></div><button class="icon-action" data-learning-delete="link" data-index="${index}">×</button></div>`).join(''); $('#linksEmpty').classList.toggle('hidden', learningData.links.length > 0); $('#learningNotes').innerHTML = learningData.notes.map((item, index) => `<article class="learning-note"><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.text).replace(/\n/g, '<br>')}</p></div><button class="icon-action" data-learning-delete="note" data-index="${index}">×</button></article>`).join(''); $('#notesEmpty').classList.toggle('hidden', learningData.notes.length > 0); renderFlow(); }
function activeFlow() { return learningData.flows.find(flow => flow.id === learningData.activeFlowId) || learningData.flows[0]; }
let flowSourceId = null;
function renderFlow() { const canvas = $('#flowCanvas'); if (!canvas) return; const flow = activeFlow(); const edges = $('#flowEdges'); const width = Math.max(canvas.clientWidth || 800, 800); const height = Math.max(canvas.clientHeight || 420, 420); edges.setAttribute('viewBox', `0 0 ${width} ${height}`); edges.innerHTML = '<defs><marker id="flowArrow" markerWidth="14" markerHeight="14" refX="12" refY="7" orient="auto"><path d="M0,0 L0,14 L14,7 z" fill="#0b8f87"/></marker></defs>' + flow.edges.map(edge => { const from = flow.nodes.find(node => node.id === edge.from); const to = flow.nodes.find(node => node.id === edge.to); if (!from || !to) return ''; const startX = from.x + 90; const startY = from.y + 38; const endX = to.x + 90; const endY = to.y + 38; const bend = Math.max(Math.abs(endX - startX) * .35, 40); return `<path d="M ${startX} ${startY} C ${startX + bend} ${startY}, ${endX - bend} ${endY}, ${endX} ${endY}" fill="none" stroke="#0b8f87" stroke-width="4" stroke-linecap="round" marker-end="url(#flowArrow)"/>`; }).join(''); $('#flowNodes').innerHTML = flow.nodes.map(node => `<button class="flow-node shape-${node.shape || 'process'} ${node.id === flowSourceId ? 'selected' : ''}" data-flow-node="${node.id}" style="left:${node.x}px;top:${node.y}px">${escapeHtml(node.label)}<span>×</span></button>`).join(''); $('#flowSelector').innerHTML = learningData.flows.map(item => `<option value="${item.id}" ${item.id === learningData.activeFlowId ? 'selected' : ''}>${escapeHtml(item.name)}</option>`).join(''); }
function addFlowNode() { const flow = activeFlow(); const label = prompt('Nome da etapa:'); if (!label?.trim()) return; flow.nodes.push({ id: newId(), label: label.trim(), shape: $('#flowShape').value || 'process', x: 30 + (flow.nodes.length % 4) * 190, y: 35 + Math.floor(flow.nodes.length / 4) * 90 }); saveLearning(); renderFlow(); }
function createFlow() { const name = prompt('Nome do novo fluxograma:'); if (!name?.trim()) return; const flow = { id: newId(), name: name.trim(), nodes: [], edges: [] }; learningData.flows.push(flow); learningData.activeFlowId = flow.id; saveLearning(); renderFlow(); }
function renameFlow() { const flow = activeFlow(); const name = prompt('Novo nome do fluxograma:', flow.name); if (name?.trim()) { flow.name = name.trim(); saveLearning(); renderFlow(); } }
function addLearningNote() { const title = prompt('Título da anotação:'); if (!title?.trim()) return; const text = prompt('Escreva o conteúdo, passo a passo ou regra do processo:'); if (!text?.trim()) return; learningData.notes.unshift({ title: title.trim(), text: text.trim(), createdAt: Date.now() }); saveLearning(); renderLearning(); }
function addLearningLink() { const url = prompt('Cole a URL:'); if (!url?.trim()) return; const title = prompt('Nome do link:') || url; learningData.links.unshift({ title: title.trim(), url: url.trim() }); saveLearning(); renderLearning(); }
function handleLearningFiles(files) { [...files].forEach(file => { if (file.size > 4 * 1024 * 1024) { alert(`${file.name} é maior que 4 MB e não foi adicionado. Use um arquivo menor para manter o armazenamento local estável.`); return; } const reader = new FileReader(); reader.onload = () => { learningData.resources.unshift({ name: file.name, type: file.type, size: `${Math.ceil(file.size / 1024)} KB`, data: reader.result, createdAt: Date.now() }); saveLearning(); renderLearning(); }; reader.readAsDataURL(file); }); }
function downloadFile(name, content, type) { const link = document.createElement('a'); const url = URL.createObjectURL(new Blob([content], { type })); link.href = url; link.download = name; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
function exportJson() { downloadFile(`backup-plantao-${today()}.json`, JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), tasks, billingHistory, mergeRows, learningData }, null, 2), 'application/json;charset=utf-8'); }
function importJson(file) { const reader = new FileReader(); reader.onload = () => { try { const backup = JSON.parse(reader.result); if (!Array.isArray(backup.tasks) || !Array.isArray(backup.billingHistory) || !Array.isArray(backup.mergeRows) || !backup.learningData) throw new Error('formato'); tasks = backup.tasks; billingHistory = backup.billingHistory; mergeRows = backup.mergeRows; learningData = backup.learningData; localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); localStorage.setItem(HISTORY_KEY, JSON.stringify(billingHistory)); localStorage.setItem(MERGE_QUEUE_KEY, JSON.stringify(mergeRows)); localStorage.setItem(LEARNING_KEY, JSON.stringify(learningData)); save(); saveHistory(); saveMergeQueue(); saveLearning(); render(); renderHistory(); renderMergePreview(); renderLearning(); alert('Backup restaurado com sucesso.'); } catch { alert('Este arquivo não é um backup JSON válido do Plantão de Demandas.'); } }; reader.readAsText(file, 'utf-8'); }
function taskStatusLabel(status) { return status === 'done' ? 'CONCLUÍDA' : status === 'progress' ? 'EM ANDAMENTO' : 'PENDENTE'; }
function exportTxt() { const selected = tasks.filter(task => task.due === today()); const lines = [`CHECKLIST DE ATIVIDADES ${new Date().toLocaleDateString('pt-BR')}`, '']; selected.forEach(task => lines.push(`* [${taskStatusLabel(task.status)}] ${task.title} — Responsável: ${task.owner}`)); if (!selected.length) lines.push('Nenhuma atividade cadastrada para hoje.'); downloadFile('checklist-atividades-hoje.txt', lines.join('\n'), 'text/plain;charset=utf-8'); }
function csvCell(value) { return `"${String(value).replace(/"/g, '""')}"`; }
function chartImage(title, labels, values, color) { const canvas = document.createElement('canvas'); canvas.width = 720; canvas.height = 300; const context = canvas.getContext('2d'); context.fillStyle = '#ffffff'; context.fillRect(0, 0, canvas.width, canvas.height); context.fillStyle = '#17232f'; context.font = 'bold 22px Arial'; context.fillText(title, 24, 34); const max = Math.max(...values, 1); labels.forEach((label, index) => { const y = 70 + index * 65; const width = values[index] ? Math.max(values[index] / max * 500, 12) : 0; context.fillStyle = '#edf1f2'; context.fillRect(150, y, 500, 28); context.fillStyle = color[index % color.length]; context.fillRect(150, y, width, 28); context.fillStyle = '#52616a'; context.font = '16px Arial'; context.fillText(label, 24, y + 20); context.fillStyle = '#17232f'; context.font = 'bold 16px Arial'; context.fillText(String(values[index]), 665, y + 20); }); return canvas.toDataURL('image/png'); }
async function exportXlsx() { if (!window.ExcelJS) throw new Error('ExcelJS não foi carregado pelas CDNs'); const selected = reportTasks(); const workbook = new ExcelJS.Workbook(); workbook.creator = 'Plantão de Demandas'; const detail = workbook.addWorksheet('Demandas'); detail.columns = [{ header: 'Demanda', key: 'title', width: 48 }, { header: 'Prazo', key: 'due', width: 14 }, { header: 'Responsável', key: 'owner', width: 16 }, { header: 'Prioridade', key: 'priority', width: 14 }, { header: 'Status', key: 'status', width: 16 }, { header: 'Criada em', key: 'created', width: 20 }, { header: 'Concluída em', key: 'completed', width: 20 }, { header: 'Observação', key: 'notes', width: 48 }]; detail.getRow(1).font = { bold: true, color: { argb: 'FFFFFFFF' } }; detail.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF087F78' } }; selected.forEach(task => detail.addRow({ title: task.title, due: task.due, owner: task.owner, priority: priorityNames[task.priority], status: task.status === 'done' ? 'Concluída' : task.status === 'progress' ? 'Em andamento' : 'Pendente', created: dateTimeLabel(task.createdAt), completed: dateTimeLabel(task.completedAt), notes: task.notes })); detail.autoFilter = 'A1:H1'; const summary = workbook.addWorksheet('Resumo e gráficos'); summary.getCell('A1').value = 'RELATÓRIO DO PLANTÃO'; summary.getCell('A1').font = { bold: true, size: 18, color: { argb: 'FF087F78' } }; summary.getCell('A2').value = `Período: ${$('#reportStart').value || 'início'} até ${$('#reportEnd').value || 'fim'}`; summary.getCell('A3').value = 'Indicador'; summary.getCell('B3').value = 'Valor'; [['Total de demandas', selected.length], ['Concluídas', selected.filter(t => normalizedStatus(t) === 'done').length]].forEach(row => summary.addRow(row)); const statusLabels = ['Pendentes', 'Andamento', 'Concluídas']; const statusValues = [selected.filter(t => normalizedStatus(t) === 'todo').length, selected.filter(t => normalizedStatus(t) === 'progress').length, selected.filter(t => normalizedStatus(t) === 'done').length]; const ownerLabels = ['Kaynan', 'Pedro']; const ownerValues = [selected.filter(t => (t.owner || 'Eu') === 'Eu').length, selected.filter(t => t.owner === 'Pedro').length]; const statusImage = workbook.addImage({ base64: chartImage('Status das demandas', statusLabels, statusValues, ['#c88921', '#3d72b8', '#0b8f87']), extension: 'png' }); const ownerImage = workbook.addImage({ base64: chartImage('Distribuição por responsável', ownerLabels, ownerValues, ['#0b8f87', '#3d72b8']), extension: 'png' }); summary.addImage(statusImage, 'A8:H22'); summary.addImage(ownerImage, 'A24:H38'); summary.getColumn(1).width = 28; summary.getColumn(2).width = 20; const buffer = await workbook.xlsx.writeBuffer(); downloadFile('relatorio-demandas.xlsx', buffer, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'); }
function chart(target, values, colors) { const max = Math.max(...values.map(item => item.value), 1); $(target).innerHTML = values.map((item, index) => `<div class="bar-row"><span>${item.label}</span><div class="bar-track"><i style="width:${Math.max(item.value / max * 100, item.value ? 8 : 0)}%;background:${colors[index]}"></i></div><strong>${item.value}</strong></div>`).join(''); }
function renderPersonReport(target, owner, selected) { const personTasks = selected.filter(t => (t.owner || 'Eu') === owner); const done = personTasks.filter(t => normalizedStatus(t) === 'done'); const created = personTasks.filter(t => t.createdAt).length; $(target).innerHTML = `<div class="person-metrics"><strong>${personTasks.length}</strong><span>demandas no período</span><strong>${done.length}</strong><span>concluídas no período</span><strong>${created}</strong><span>com data de criação</span></div>`; }
function renderReports() { const selected = reportTasks(); const active = selected.filter(t => normalizedStatus(t) !== 'done'); const user = window.PortalAccess?.Access?.user; const users = user?.role === 'admin' ? (window.__portalUsers || []) : [user, ...(user?.teammates || [])]; const people = [...new Map(users.filter(Boolean).map(item => [item.displayName, item.displayName])).values()]; chart('#statusChart', [{ label: 'Pendentes', value: selected.filter(t => normalizedStatus(t) === 'todo').length }, { label: 'Andamento', value: selected.filter(t => normalizedStatus(t) === 'progress').length }, { label: 'Concluídas', value: selected.filter(t => normalizedStatus(t) === 'done').length }], ['#c88921', '#3d72b8', '#0b8f87']); chart('#priorityChart', Object.entries(priorityNames).map(([key, label]) => ({ label, value: active.filter(t => t.priority === key).length })), ['#d94c52', '#c88921', '#3d72b8', '#89969d']); chart('#ownerChart', people.map(label => ({ label, value: active.filter(t => (t.owner || '') === label).length })), people.map((_, index) => ['#0b8f87', '#3d72b8', '#89969d', '#c88921'][index % 4])); $('#individualReports').innerHTML = people.map((name, index) => `<article class="report-card individual-report"><h3>Relatório de ${escapeHtml(name)}</h3><div id="report-person-${index}"></div></article>`).join(''); people.forEach((name, index) => renderPersonReport(`#report-person-${index}`, name, selected)); $('#reportDate').textContent = `${selected.length} demandas no período`; }
function escapeHtml(value) { return String(value || '').replace(/[&<>'"]/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', "'":'&#39;', '"':'&quot;' }[c])); }
function moneyValue(value) { return Number(value.replace(/\./g, '').replace(',', '.')); }
function moneyLabel(value) { return `R$ ${value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`; }
function parseFinancialText(text) { const matches = [...text.matchAll(/Vencimento\s*:\s*(\d{2}\/\d{2}\/\d{4})/gi)]; const currentDate = today(); const entries = matches.map((match, index) => { const block = text.slice(match.index, matches[index + 1]?.index || text.length); const [, day, month, year] = match[1].match(/(\d{2})\/(\d{2})\/(\d{4})/); const date = `${year}-${month}-${day}`; const due = new Date(`${date}T12:00:00`); const titleMatch = block.match(/(?:Título|Titulo)[^\d]{0,24}([\d.]+,\d{2})/i); const finalMatch = block.match(/Valor final[^\d]{0,24}([\d.]+,\d{2})/i); const title = titleMatch ? moneyValue(titleMatch[1]) : null; const final = finalMatch ? moneyValue(finalMatch[1]) : null; const amount = date >= currentDate ? title ?? final : final ?? title; return { date, label: `${due.toLocaleDateString('pt-BR', { month: 'long' }).toUpperCase()} - ${amount == null ? 'VALOR NÃO IDENTIFICADO' : moneyLabel(amount)}`, amount, title, final }; }).filter(entry => entry.amount != null).sort((a, b) => b.date.localeCompare(a.date)); return entries.slice(0, 3).map(entry => entry.label); }
function renderMergePreview() { if (!mergeRows.length) return; $('#mergePreview').classList.remove('hidden'); const header = '<strong>EMPRESA</strong><strong>EMAIL</strong><strong>COMP1</strong><strong>COMP2</strong><strong>COMP3</strong><strong>AÇÕES</strong>'; const rows = mergeRows.map((row, index) => `<input data-merge-field="EMPRESA" data-index="${index}" value="${escapeHtml(row.EMPRESA)}"><input data-merge-field="EMAIL" data-index="${index}" value="${escapeHtml(row.EMAIL)}"><input data-merge-field="COMP1" data-index="${index}" value="${escapeHtml(row.COMP1 || '')}"><input data-merge-field="COMP2" data-index="${index}" value="${escapeHtml(row.COMP2 || '')}"><input data-merge-field="COMP3" data-index="${index}" value="${escapeHtml(row.COMP3 || '')}"><span class="queue-actions"><button data-queue-action="up" data-index="${index}" ${index === 0 ? 'disabled' : ''}>↑</button><button data-queue-action="down" data-index="${index}" ${index === mergeRows.length - 1 ? 'disabled' : ''}>↓</button><button data-queue-action="delete" data-index="${index}">Excluir</button></span>`).join(''); $('#mergePreviewContent').innerHTML = `<div class="merge-row merge-queue">${header}${rows}</div>`; $('#mergeQueueNote').textContent = `${mergeRows.length} linha(s) pronta(s) para a mala direta.`; }
function extractCompanyAndEmails(text) { const commercialMatch = text.match(/Empresa\s*\d+\s*-\s*([\s\S]*?)(?=Raz[aã]o Social|Tipo de empresa|Grupo|Centro de custo|Situa[cç][aã]o)/i); const legalMatch = text.match(/Raz[aã]o Social\s*[:\-]?\s*(.+?)(?=Tipo de empresa|Grupo|Centro de custo|Situa[cç][aã]o|\r?\n|$)/i) || text.match(/Raz[aã]o Social\s*[:\-]?\s*([^\r\n]+)/i); const blockedEmails = new Set(['carla.vieira@appredesaude.com.br']); const labeledEmails = [...text.matchAll(/E-?mail\s*[:\-]?\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/gi)].map(match => match[1].toLowerCase()); const separatedEmails = [...text.matchAll(/(?:^|[\s,;])([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/gi)].map(match => match[1].replace(/^e-?mail/i, '').toLowerCase()); const emails = [...new Set([...labeledEmails, ...separatedEmails])].filter(email => !blockedEmails.has(email)); return { commercial: commercialMatch ? commercialMatch[1].replace(/\s+/g, ' ').trim() : '', legal: legalMatch ? legalMatch[1].replace(/\s+/g, ' ').trim() : '', emails: emails.join(', ') }; }
function parseMerge() { const extracted = extractCompanyAndEmails($('#financialText').value); const company = $('#mergeNameMode').value === 'legal' ? extracted.legal : extracted.commercial; if (company) $('#mergeCompany').value = company; if (extracted.emails) $('#mergeEmail').value = extracted.emails; const selectedCompany = $('#mergeCompany').value.trim(); const email = $('#mergeEmail').value.trim(); const competencies = parseFinancialText($('#financialText').value); if (!selectedCompany || !email || !competencies.length) { alert('Cole a página completa ou informe empresa, e-mail e um texto com vencimentos e valores identificáveis.'); return; } mergeRows.push({ EMPRESA: selectedCompany, EMAIL: email, COMP1: competencies[0] || '', COMP2: competencies[1] || '', COMP3: competencies[2] || '' }); saveMergeQueue(); renderMergePreview(); }
function renderHistory() { const grouped = billingHistory.reduce((result, item) => { const key = item.company.toUpperCase(); result[key] ||= { company: item.company, emails: item.emails, dates: [], competencies: [] }; result[key].dates.push(item.date); result[key].competencies.push(...item.competencies.filter(Boolean)); return result; }, {}); const rows = Object.values(grouped).sort((a, b) => b.dates[0].localeCompare(a.dates[0])); $('#historyBody').innerHTML = rows.map(row => { const sortedDates = [...row.dates].sort(); return `<tr><td><strong>${escapeHtml(row.company)}</strong></td><td>${escapeHtml(row.emails)}</td><td>${sortedDates.map(date => dateLabel(date)).join(', ')}</td><td><span class="history-count">${row.dates.length}x</span></td><td>${escapeHtml([...new Set(row.competencies)].join(' | '))}</td></tr>`; }).join(''); $('#historyEmpty').classList.toggle('hidden', rows.length > 0); $('#historySummary').textContent = `${billingHistory.length} cobrança(s) registrada(s)`; }
function registerBillingHistory() { mergeRows.forEach(row => billingHistory.push({ company: row.EMPRESA, emails: row.EMAIL, date: today(), competencies: [row.COMP1, row.COMP2, row.COMP3] })); saveHistory(); renderHistory(); }
