function openDialog(task = null, initialDate = null) { editingId = task?.id || null; const user = window.PortalAccess?.Access?.user; checklistDraft = (task?.checklist || []).map(item => ({ ...item })); attachmentDraft = (task?.attachments || []).map(item => ({ ...item })); $('#dialogEyebrow').textContent = task ? 'EDITAR DEMANDA' : 'NOVA ENTRADA'; $('#dialogTitle').textContent = task ? 'Atualizar demanda' : 'Registrar demanda'; $('#saveTaskButton').textContent = task ? 'Salvar alterações' : 'Adicionar demanda'; $('#taskTitle').value = task?.title || ''; $('#taskPeriodStart').value = task?.periodStart || task?.due || initialDate || today(); $('#taskPeriodEnd').value = task?.periodEnd || task?.due || initialDate || today(); $('#taskSectorChoice').value = task?.sectorId || user?.sectorId || ''; $('#taskOwner').value = task?.owner || user?.displayName || ''; $('#taskCategory').value = task?.category || user?.sectorName || ''; $('#taskPriority').value = task?.priority || 'medium'; $('#taskRecurrence').value = task?.recurrence || 'none'; $('#taskNotes').value = task?.notes || ''; renderChecklistEditor(); renderAttachmentEditor(); $('#taskDialog').showModal(); $('#taskTitle').focus(); }
