function fillMergeFields() { const extracted = extractCompanyAndEmails($('#financialText').value); const company = $('#mergeNameMode').value === 'legal' ? extracted.legal : extracted.commercial; if (company) $('#mergeCompany').value = company; if (extracted.emails) $('#mergeEmail').value = extracted.emails; }
$('#mergePreviewContent').addEventListener('input', event => { const field = event.target.dataset.mergeField; const index = Number(event.target.dataset.index); if (field && mergeRows[index]) { mergeRows[index][field] = event.target.value; saveMergeQueue(); } }); $('#mergePreviewContent').addEventListener('click', event => { const button = event.target.closest('[data-queue-action]'); if (!button) return; const index = Number(button.dataset.index); const action = button.dataset.queueAction; if (action === 'delete') mergeRows.splice(index, 1); if (action === 'up' && index > 0) [mergeRows[index - 1], mergeRows[index]] = [mergeRows[index], mergeRows[index - 1]]; if (action === 'down' && index < mergeRows.length - 1) [mergeRows[index + 1], mergeRows[index]] = [mergeRows[index], mergeRows[index + 1]]; saveMergeQueue(); if (mergeRows.length) renderMergePreview(); else $('#mergePreview').classList.add('hidden'); });
$('#financialText').addEventListener('input', fillMergeFields); $('#mergeNameMode').addEventListener('change', fillMergeFields); $('#parseMerge').addEventListener('click', parseMerge); $('#clearMerge').addEventListener('click', () => { $('#mergeCompany').value = ''; $('#mergeEmail').value = ''; $('#financialText').value = ''; $('#mergePreview').classList.toggle('hidden', !mergeRows.length); renderMergePreview(); }); $('#addMergeRow').addEventListener('click', () => { $('#mergeCompany').value = ''; $('#mergeEmail').value = ''; $('#financialText').value = ''; $('#mergePreview').classList.toggle('hidden', !mergeRows.length); renderMergePreview(); }); $('#downloadMerge').addEventListener('click', downloadMergeWorkbook); $('#mergeTemplate').addEventListener('change', async event => { const file = event.target.files[0]; if (file) { mergeTemplateBuffer = await file.arrayBuffer(); $('#mergeQueueNote').textContent = `Modelo carregado: ${file.name}. As novas linhas serão adicionadas abaixo do conteúdo existente.`; } });
$('#taskList').addEventListener('change', event => { const input = event.target.closest('[data-checklist-task]'); if (!input) return; const task = tasks.find(item => item.id === input.dataset.checklistTask); const item = task?.checklist?.[Number(input.dataset.checklistIndex)]; if (!item) return; item.done = input.checked; touchTask(task); save(); render(); }); $('#taskList').addEventListener('click', (event) => { const button = event.target.closest('[data-action]'); if (!button) return; const task = tasks.find(t => t.id === button.dataset.id); if (button.dataset.action === 'toggle') completeTask(task); if (button.dataset.action === 'claim') claimTask(task); if (button.dataset.action === 'add-checklist') { addTaskChecklistItem(task); return; } if (button.dataset.action === 'edit') openDialog(task); if (button.dataset.action === 'delete' && confirm(`Excluir a demanda "${task.title}"?`)) { deletedTaskIds.add(task.id); localStorage.setItem(DELETED_TASKS_KEY, JSON.stringify([...deletedTaskIds])); tasks = tasks.filter(t => t.id !== button.dataset.id); } save(); render(); if (!$('#reports').classList.contains('hidden')) renderReports(); });
function playCompletionSound() { try { const context = new AudioContext(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.frequency.value = 880; oscillator.type = 'sine'; gain.gain.setValueAtTime(.18, context.currentTime); gain.gain.exponentialRampToValueAtTime(.001, context.currentTime + .35); oscillator.connect(gain).connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + .35); } catch {} }
function completeTask(task) { if (task.status === 'done') { task.status = 'todo'; delete task.completedAt; touchTask(task); return; } task.status = 'done'; task.completedAt = new Date().toISOString(); touchTask(task); playCompletionSound(); if (task.recurrence !== 'none') { const nextStart = nextOccurrence(task.periodStart || task.due, task.recurrence); const nextEnd = nextOccurrence(task.periodEnd || task.due, task.recurrence); tasks.push({ ...task, id: newId(), due: nextEnd, periodStart: nextStart, periodEnd: nextEnd, status: 'todo', createdAt: new Date().toISOString(), updatedAt: new Date().toISOString(), completedAt: null }); } }
let reminderQueue = [];
let reminderTimer = null;
function requestNotificationPermission() { if (!('Notification' in window) || !window.isSecureContext) return; if (Notification.permission === 'default') Notification.requestPermission(); }
function sendNextReminder() { if (!reminderQueue.length || !('Notification' in window) || Notification.permission !== 'granted') return; const task = reminderQueue.shift(); const notified = new Set(JSON.parse(sessionStorage.getItem('portal-notified-tasks') || '[]')); notified.add(task.id); sessionStorage.setItem('portal-notified-tasks', JSON.stringify([...notified])); const notification = new Notification('Check-in de atividade', { body: `${task.title} · responsável: ${task.owner}`, tag: `task-${task.id}`, requireInteraction: true }); notification.onclick = () => { const currentTask = tasks.find(item => item.id === task.id); if (currentTask && currentTask.status !== 'done') { completeTask(currentTask); save(); render(); if (!$('#reports').classList.contains('hidden')) renderReports(); } notification.close(); }; }
function checkReminder() { if (!('Notification' in window) || !window.isSecureContext || Notification.permission !== 'granted' || reminderTimer) return; const candidates = scopedTasks().filter(task => task.status !== 'done' && task.due <= today()); const notified = new Set(JSON.parse(sessionStorage.getItem('portal-notified-tasks') || '[]')); reminderQueue = candidates.filter(task => !notified.has(task.id)); if (!reminderQueue.length) return; sendNextReminder(); reminderTimer = setInterval(() => { sendNextReminder(); if (!reminderQueue.length) { clearInterval(reminderTimer); reminderTimer = null; } }, 50 * 60 * 1000); }
$('#reminderDone').addEventListener('click', () => { const task = tasks.find(item => item.id === reminderTaskId); if (task) completeTask(task); save(); render(); $('#reminderDialog').close(); }); $('#reminderLater').addEventListener('click', () => $('#reminderDialog').close());
async function bootstrap() { try { const response = await fetch(`${window.PORTAL_API_BASE || ''}/api/state`, { headers: window.PortalAccess.authHeaders() }); if (response.status === 401) return; const state = await response.json(); if (state.tasks || state.billingHistory || state.mergeRows || state.learningData) { tasks = normalizeTasks(state.tasks || tasks); deletedTaskIds = new Set(state.deletedTaskIds || [...deletedTaskIds]); billingHistory = state.billingHistory || billingHistory; mergeRows = state.mergeRows || mergeRows; learningData = state.learningData || learningData; localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); localStorage.setItem(DELETED_TASKS_KEY, JSON.stringify([...deletedTaskIds])); localStorage.setItem(HISTORY_KEY, JSON.stringify(billingHistory)); localStorage.setItem(MERGE_QUEUE_KEY, JSON.stringify(mergeRows)); localStorage.setItem(LEARNING_KEY, JSON.stringify(learningData)); persistBackend(); } else { seedIfEmpty(); } } catch { tasks = normalizeTasks(tasks); seedIfEmpty(); } render(); renderHistory(); renderMergePreview(); renderLearning(); }
window.bootstrapPortal = bootstrap;
window.PortalAccess.restoreSession().then(ok => { if (ok) bootstrap(); });

// ===== Sincronização automática entre notebooks (servidor central) =====
let syncing = false;
async function syncFromServer() {
  if (syncing || !window.PortalAccess?.Access?.token) return;
  const active = document.activeElement;
  if (active && ['INPUT', 'TEXTAREA', 'SELECT'].includes(active.tagName)) return;
  syncing = true;
  try {
    const response = await fetch(`${window.PORTAL_API_BASE || ''}/api/state`, { headers: window.PortalAccess.authHeaders() });
    if (!response.ok) return;
    const state = await response.json();
    if (!state.tasks && !state.billingHistory && !state.mergeRows && !state.learningData) return;
    const current = JSON.stringify({ tasks, billingHistory, mergeRows, learningData });
    const incoming = JSON.stringify(state);
    if (incoming === current) return;
    tasks = normalizeTasks(state.tasks || tasks);
    deletedTaskIds = new Set(state.deletedTaskIds || [...deletedTaskIds]);
    billingHistory = state.billingHistory || billingHistory;
    mergeRows = state.mergeRows || mergeRows;
    learningData = state.learningData || learningData;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
    localStorage.setItem(DELETED_TASKS_KEY, JSON.stringify([...deletedTaskIds]));
    localStorage.setItem(HISTORY_KEY, JSON.stringify(billingHistory));
    localStorage.setItem(MERGE_QUEUE_KEY, JSON.stringify(mergeRows));
    localStorage.setItem(LEARNING_KEY, JSON.stringify(learningData));
    render(); renderHistory(); renderMergePreview(); renderLearning();
  } catch {} finally { syncing = false; }
}
setInterval(syncFromServer, 8000);
document.addEventListener('visibilitychange', () => { if (!document.hidden) syncFromServer(); });

setTimeout(checkReminder, 8000); setInterval(checkReminder, 50 * 60 * 1000); $('#loginForm').addEventListener('submit', requestNotificationPermission, { once: true });

// ===== Relatório Semanal =====
let weeklyOffset = 0;
$('#recordDate').value = today();
function weekRange(offset = weeklyOffset) { const base = new Date(); base.setDate(base.getDate() + offset * 7); const shift = (base.getDay() + 6) % 7; const start = new Date(base); start.setDate(base.getDate() - shift); const end = new Date(start); end.setDate(start.getDate() + 6); return { start: start.toISOString().slice(0, 10), end: end.toISOString().slice(0, 10) }; }
function weekLabelDate(date) { return new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' }); }
function weekdayLong(date) { return new Date(`${date}T12:00:00`).toLocaleDateString('pt-BR', { weekday: 'long' }); }
function weekRecords() { const range = weekRange(); const user = window.PortalAccess?.Access?.user; return learningData.weeklyRecords.filter(item => item.date >= range.start && item.date <= range.end && (user?.role === 'admin' || item.sectorId === user?.sectorId || (!item.sectorId && user?.sectorId === 'cadastro-faturamento'))); }
function renderWeekly() { const range = weekRange(); const selected = weekRecords(); const companies = selected.filter(item => item.kind === 'empresa'); const establishments = selected.filter(item => item.kind === 'estabelecimento'); $('#weekLabel').textContent = `${weekLabelDate(range.start)} – ${weekLabelDate(range.end)}`; $('#weekCurrentTag').classList.toggle('hidden', weeklyOffset !== 0); $('#weeklyCompanyCount').textContent = companies.length; $('#weeklyEstablishmentCount').textContent = establishments.length; $('#weeklyTotalCount').textContent = selected.length; const sorted = [...selected].sort((a, b) => a.date.localeCompare(b.date) || a.kind.localeCompare(b.kind) || a.name.localeCompare(b.name)); $('#weeklyBody').innerHTML = sorted.map(item => `<tr><td><span class="week-day">${escapeHtml(weekdayLong(item.date))}</span>${weekLabelDate(item.date)}</td><td><span class="badge kind-${item.kind}">${item.kind === 'empresa' ? 'Empresa' : 'Estabelecimento'}</span></td><td><strong>${escapeHtml(item.name)}</strong></td><td class="week-actions"><button class="delete" data-weekly-delete="${item.id}" aria-label="Remover registro">×</button></td></tr>`).join(''); $('#weeklyEmpty').classList.toggle('hidden', selected.length > 0); $('#weeklySummary').textContent = `${companies.length} ${companies.length === 1 ? 'empresa' : 'empresas'} e ${establishments.length} ${establishments.length === 1 ? 'estabelecimento' : 'estabelecimentos'} no período`; }
function weeklyReportText() { const range = weekRange(); const selected = weekRecords(); const period = `Período: ${new Date(`${range.start}T12:00:00`).toLocaleDateString('pt-BR')} a ${new Date(`${range.end}T12:00:00`).toLocaleDateString('pt-BR')}`; const lines = ['RELATÓRIO SEMANAL DE CADASTROS', period, '']; [['EMPRESAS CADASTRADAS', 'empresa', 'Nenhuma empresa cadastrada nesta semana'], ['ESTABELECIMENTOS CADASTRADOS', 'estabelecimento', 'Nenhum estabelecimento cadastrado nesta semana']].forEach(([heading, kind, empty]) => { const items = selected.filter(item => item.kind === kind).sort((a, b) => a.date.localeCompare(b.date)); lines.push(`${heading} (${items.length})`); items.forEach(item => lines.push(`- ${item.name} — ${weekdayLong(item.date)}, ${weekLabelDate(item.date)}`)); if (!items.length) lines.push(empty); lines.push(''); }); return lines.join('\n').trimEnd(); }
async function copyWeeklyReport() { const text = weeklyReportText(); try { await navigator.clipboard.writeText(text); } catch { const area = document.createElement('textarea'); area.value = text; document.body.appendChild(area); area.select(); document.execCommand('copy'); area.remove(); } const button = $('#copyWeeklyReport'); button.textContent = 'Mensagem copiada!'; setTimeout(() => { button.textContent = 'Copiar mensagem para envio'; }, 2000); }
async function exportWeeklyXlsx() {
  if (!window.ExcelJS) throw new Error('ExcelJS não foi carregado pelas CDNs');
  const range = weekRange(); const selected = weekRecords();
  const workbook = new ExcelJS.Workbook(); workbook.creator = 'Plantão de Demandas';
  const sheet = workbook.addWorksheet('Relatório Semanal');
  sheet.getCell('A1').value = 'RELATÓRIO SEMANAL DE CADASTROS'; sheet.getCell('A1').font = { bold: true, size: 16, color: { argb: 'FF087F78' } };
  sheet.getCell('A2').value = `Período: ${new Date(`${range.start}T12:00:00`).toLocaleDateString('pt-BR')} a ${new Date(`${range.end}T12:00:00`).toLocaleDateString('pt-BR')}`; sheet.getCell('A2').font = { color: { argb: 'FF70808C' } };
  let row = 4;
  [['EMPRESAS CADASTRADAS', 'empresa', 'Empresa'], ['ESTABELECIMENTOS CADASTRADOS', 'estabelecimento', 'Estabelecimento']].forEach(([heading, kind, column]) => {
    sheet.getCell(`A${row}`).value = heading; sheet.getCell(`A${row}`).font = { bold: true, size: 12 }; row += 1;
    const header = sheet.getRow(row); header.values = [column, 'Dia', 'Data']; header.font = { bold: true, color: { argb: 'FFFFFFFF' } }; header.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF087F78' } }; row += 1;
    const items = selected.filter(item => item.kind === kind).sort((a, b) => a.date.localeCompare(b.date));
    if (!items.length) { sheet.getCell(`A${row}`).value = 'Nenhum cadastro no período'; row += 1; } else items.forEach(item => { sheet.getRow(row).values = [item.name, weekdayLong(item.date), new Date(`${item.date}T12:00:00`).toLocaleDateString('pt-BR')]; row += 1; });
    row += 2;
  });
  sheet.getColumn(1).width = 46; sheet.getColumn(2).width = 24; sheet.getColumn(3).width = 14;
  const buffer = await workbook.xlsx.writeBuffer();
  downloadFile(`relatorio-semanal-${range.start}_a_${range.end}.xlsx`, buffer, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
}
$('#weeklyQuickForm').addEventListener('submit', event => { event.preventDefault(); const name = $('#recordName').value.trim(); if (!name) return; const user = window.PortalAccess?.Access?.user; learningData.weeklyRecords.push({ id: newId(), kind: $('#recordKind').value, name, date: $('#recordDate').value || today(), createdBy: $('#recordOwner').value, sectorId: user?.sectorId || null }); saveLearning(); renderWeekly(); $('#recordName').value = ''; $('#recordName').focus(); });
$('#weeklyBody').addEventListener('click', event => { const button = event.target.closest('[data-weekly-delete]'); if (!button) return; const record = learningData.weeklyRecords.find(item => item.id === button.dataset.weeklyDelete); if (!record) return; if (confirm(`Remover o registro "${record.name}"?`)) { learningData.weeklyRecords = learningData.weeklyRecords.filter(item => item.id !== record.id); saveLearning(); renderWeekly(); } });
